static int resv_report(int argc, char **argv, struct command *acmd, struct plugin *plugin)
{
	return forward_to_resv_plugin("resv-report", "report", argc, argv);
}

static inline void
nvme_init_resv_report(struct libnvme_passthru_cmd *cmd, __u32 nsid,
		bool eds, bool disnsrs, struct nvme_resv_status *report,
		__u32 len)
{
	memset(cmd, 0, sizeof(*cmd));

	cmd->opcode = nvme_cmd_resv_report;
	cmd->nsid = nsid;
	cmd->data_len = len;
	cmd->addr = (__u64)(uintptr_t)report;
	cmd->cdw10 = (len >> 2) - 1;
	cmd->cdw11 = NVME_FIELD_ENCODE(eds,
			NVME_RESV_REPORT_CDW11_EDS_SHIFT,
			NVME_RESV_REPORT_CDW11_EDS_MASK) |
		     NVME_FIELD_ENCODE(disnsrs,
			NVME_RESV_REPORT_CDW11_DISNSRS_SHIFT,
			NVME_RESV_REPORT_CDW11_DISNSRS_MASK);
}

void json_nvme_resv_report(struct nvme_resv_status *status,
			   int bytes, bool eds)
{
	struct json_object *r = json_r;
	struct json_object *rcs = json_create_array();
	int i, j, entries;
	int regstrnt = status->regstrnt[0] | (status->regstrnt[1] << 8);

	obj_add_uint(r, "gen", le32_to_cpu(status->gen));
	obj_add_int(r, "rtype", status->rtype);
	obj_add_int(r, "regstrnt", regstrnt);
	obj_add_int(r, "ptpls", status->ptpls);

	/* check Extended Data Structure bit */
	if (!eds) {
		/*
		 * if status buffer was too small, don't loop past the end of
		 * the buffer
		 */
		entries = (bytes - 24) / 24;
		if (entries < regstrnt)
			regstrnt = entries;

		obj_add_array(r, "registrants", rcs);

static void stdout_resv_report(struct nvme_resv_status *status, int bytes,
			       bool eds)
{
	struct shr_table *t;
	int i, j, regstrnt, entries;
	char hex[33], *hp;

	regstrnt = status->regstrnt[0] | (status->regstrnt[1] << 8);

	printf("\nNVME Reservation status:\n\n");

	t = stdout_kv_table_create();
	if (!t)
		return;

	stdout_kv_add(t, "gen", "%u", le32_to_cpu(status->gen));
	stdout_kv_add(t, "rtype", "%d", status->rtype);
	stdout_kv_add(t, "regstrnt", "%d", regstrnt);
	stdout_kv_add(t, "ptpls", "%d", status->ptpls);

	stdout_kv_table_finish(t, "resv-report");

	/* check Extended Data Structure bit */
	if (!eds) {

	for (i = 0; i < regstrnt; i++) {
		struct json_object *rc = json_create_object();

		obj_add_int(rc, "cntlid", le16_to_cpu(status->registrant_ds[i].cntlid));
		obj_add_int(rc, "rcsts", status->registrant_ds[i].rcsts);
		obj_add_uint64(rc, "hostid", le64_to_cpu(status->registrant_ds[i].hostid));
		obj_add_uint64(rc, "rkey", le64_to_cpu(status->registrant_ds[i].rkey));

		array_add_obj(rcs, rc);
	}
} else {
	char hostid[33];

	/* if status buffer was too small, don't loop past the end of the buffer */
	entries = (bytes - 64) / 64;

	if (entries < regstrnt)
		regstrnt = entries;

	obj_add_array(r, "registrantext", rcs);

	for (i = 0; i < regstrnt; i++) {
		struct json_object *rc = json_create_object();

			obj_add_int(rc, "cntlid", le16_to_cpu(status->registrant_eds[i].cntlid));
			obj_add_int(rc, "rcsts", status->registrant_eds[i].rcsts);
			obj_add_uint64(rc, "rkey", le64_to_cpu(status->registrant_eds[i].rkey));

			for (j = 0; j < 16; j++)
				sprintf(hostid + j * 2, "%02x", status->registrant_eds[i].hostid[j]);

			obj_add_str(rc, "hostid", hostid);
			array_add_obj(rcs, rc);
		}
	}
}

void json_fw_log(struct nvme_firmware_slot *fw_log, const char *devname)
{
	struct json_object *r = json_r;
	struct json_object *fwsi = json_create_object();
	char fmt[21];
	char str[32];
	int i;
	__le64 *frs;

	obj_add_int(fwsi, "Active Firmware Slot (afi)", fw_log->afi);

	for (i = 0; i < 7; i++) {
		if (fw_log->frs[i][0]) {
			snprintf(fmt, sizeof(fmt), "Firmware Rev Slot %d",
				i + 1);
			frs = (__le64 *)&fw_log->frs[i];
			snprintf(str, sizeof(str), "%"PRIu64" (%s)",
				le64_to_cpu(*frs),
			shr_fw_to_string(fw_log->frs[i]));
			obj_add_str(fwsi, fmt, str);
		}
	}

	obj_add_obj(r, devname, fwsi);

void json_changed_ns_list_log(struct nvme_ns_list *log, const char *devname, bool alloc)
{
	struct json_object *r = json_r;
	struct json_object *nsi = json_create_object();
	char fmt[32];
	char str[32];
	__u32 nsid;
	int i;

	__cleanup_free char *k = NULL;

	if (log->ns[0] == cpu_to_le32(0xffffffff))
		return;

/*
 * if status buffer was too small, don't loop past the end of
 * the buffer
 */
entries = (bytes - 24) / 24;
if (entries < regstrnt)
	regstrnt = entries;

for (i = 0; i < regstrnt; i++) {
	struct nvme_registrant *reg = &status->registrant_ds[i];

	printf("registrant[%d] :\n", i);

	t = stdout_kv_table_create();
	if (!t)
		return;
	shr_table_set_indent(t, 2);

	stdout_kv_add(t, "cntlid", "%x",
		      le16_to_cpu(reg->cntlid));
	stdout_kv_add(t, "rcsts", "%x", reg->rcsts);
	stdout_kv_add(t, "hostid", "%"PRIx64,
		      le64_to_cpu(reg->hostid));
	stdout_kv_add(t, "rkey", "%"PRIx64,

			      le64_to_cpu(reg->rkey));

		stdout_kv_table_finish(t, "registrant");
	}
} else {
	/*
	 * if status buffer was too small, don't loop past the end of
	 * the buffer
	 */
	entries = (bytes - 64) / 64;
	if (entries < regstrnt)
		regstrnt = entries;

	for (i = 0; i < regstrnt; i++) {
		struct nvme_registrant_ext *reg =
			&status->registrant_eds[i];

		printf("registrantext[%d] :\n", i);

		t = stdout_kv_table_create();
		if (!t)
			return;
		shr_table_set_indent(t, 2);

			stdout_kv_add(t, "cntlid", "%x",
				      le16_to_cpu(reg->cntlid));
			stdout_kv_add(t, "rcsts", "%x", reg->rcsts);
			stdout_kv_add(t, "rkey", "%"PRIx64,
				      le64_to_cpu(reg->rkey));

			hp = hex;
			for (j = 0; j < 16; j++)
				hp += sprintf(hp, "%02x", reg->hostid[j]);
			stdout_kv_add(t, "hostid", "%s", hex);

			stdout_kv_table_finish(t, "registrant");
		}
	}
	printf("\n");
}

static void stdout_select_result(enum nvme_features_id fid, __u64 result)
{
	struct shr_table *t;

	t = stdout_kv_table_create();
	if (!t)
		return;

	if (result & 0x1)
		stdout_kv_add(t, "", "Feature is saveable");
	if (result & 0x2)
		stdout_kv_add(t, "", "Feature is per-namespace");
	if (result & 0x4)
		stdout_kv_add(t, "", "Feature is changeable");

	stdout_kv_table_finish(t, "select-result");
}
